// Input data se raw output string ko nikalna
let rawOutput = $input.first().json.output;

// Bad control characters aur un-escaped newlines ko saaf karna
rawOutput = rawOutput
  .replace(/[\u0000-\u001F\u007F-\u009F]/g, "") // Control characters hatane ke liye
  .replace(/\n/g, "\\n")                         // Newlines ko escape karne ke liye
  .replace(/\r/g, "\\r");

try {
  // Saaf kiye huay data ko parse karna
  const parsedData = JSON.parse(rawOutput);

  return {
    json: {
      intent: parsedData.intent,
      image_prompt: parsedData.image_prompt
    }
  };
} catch (error) {
  // Agar phir bhi koi masla ho toh error handle karna
  return {
    json: {
      error: "Parsing failed: " + error.message,
      raw_string: rawOutput
    }
  };
}

