return $input.all();

for (const item of $input.all()) {
  // 1. Pehle text tak pahunchein
  let text = item.json.content.parts[0].text;

  // 2. Text ko saaf karein (Image Prompt aur \n hataiye)
  let cleanText = text.replace("Image Prompt:", "").replace(/\\n/g, "").trim();

  // 3. Usi jagah par wapas save kar dein
  item.json.content.parts[0].text = cleanText;
}

return $input.all();

// 1. Pehle node se raw text data uthein (maan lijiye variable ka naam 'text' hai)
const rawText = $input.first().json.content.parts[0].text;

// 2. Agar data pehle se string hai toh backslashes saaf karke parse karein
const cleanedText = rawText.replace(/\\"/g, '"').replace(/\\n/g, '');
const imagesArray = JSON.parse(cleanedText);

// 3. Har image ko n8n ke alag item mein convert karein
return imagesArray.map(img => {
    return {
        json: {
            image_number: img.image_number,
            prompt: img.prompt
        }
    };
});
